class ReadOnlyStreamImpl {
    constructor(element) {
        if (element == null) {
            this.element = document.createElement('div');
        }
        else {
            this.element = element;
        }
    }
    subscribe(callback) {
        const eventCallback = (event) => {
            const data = event.detail;
            callback(data);
        };
        this.element.addEventListener('stream-event', eventCallback);
        return () => {
            this.element.removeEventListener('stream-event', eventCallback);
        };
    }
}
export class Stream extends ReadOnlyStreamImpl {
    getReadOnlyStream() {
        const readOnlyStream = new ReadOnlyStreamImpl(this.element);
        return readOnlyStream;
    }
    fire(data) {
        this.element.dispatchEvent(new CustomEvent('stream-event', {
            detail: data
        }));
    }
}
